import sys
from collections import defaultdict

def countSubstring(S):
    balance = 0
    count = 0
    prefix_count = defaultdict(int)
    prefix_count[0] = 1

    for char in S:
        if char == '1':
            balance += 1
        else:
            balance -= 1

        if balance > 0:
            count += prefix_count[0] + prefix_count[balance]
        else:
            count += prefix_count[balance - 1]

        prefix_count[balance] += 1

    return count

input = sys.stdin.read().strip()
print(countSubstring(input))
